<template><q-dialog :model-value="modelValue" position="top" @update:model-value="emit('update:modelValue',$event)"><div class="command-palette" @keydown.down.prevent="move(1)" @keydown.up.prevent="move(-1)"><label class="command-search"><Icon name="search" :size="20"/><input ref="input" v-model="query" autofocus @keydown.enter.prevent="run(selected)" aria-label="Команды и плейлисты" placeholder="Команда, плейлист или трек" autocomplete="off" spellcheck="false"/><kbd>Esc</kbd></label><div class="command-results" role="listbox" aria-label="Результаты команд"><button v-for="(item,i) in results" :key="item.id" role="option" :aria-selected="i===selected" :class="{on:i===selected}" @mousemove="selected=i" @click="run(i)"><Icon :name="item.icon" :size="17"/><span>{{item.label}}</span><small>{{item.group}}</small><Icon v-if="i===selected" name="chevronRight" :size="13"/></button><p v-if="!results.length">Ничего не найдено</p></div><footer>↑ ↓ выбрать <span>Enter открыть</span></footer></div></q-dialog></template>
<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue';import {useRouter} from 'vue-router';import type {Track} from '@/api/types';import Icon from '@/components/Icon.vue';import {commandScore} from '@/lib/commandSearch';import {useWorkspaceToolsStore,type WorkspaceTool} from '@/stores/workspaceTools';import {usePlayerStore} from '@/stores/player/index';import {useLibraryStore} from '@/stores/library';import {useSleepStore} from '@/stores/sleep';
const props=defineProps<{modelValue:boolean}>(),emit=defineEmits<{'update:modelValue':[value:boolean]}>();const router=useRouter(),tools=useWorkspaceToolsStore(),player=usePlayerStore(),library=useLibraryStore(),sleep=useSleepStore();const query=ref(''),selected=ref(0),input=ref<HTMLInputElement|null>(null);
interface Command{id:string;label:string;group:string;icon:string;keywords?:string;action:()=>void}
const route=(path:string,section?:string)=>()=>{void router.push({path,query:section?{section}:{}});};const tool=(name:WorkspaceTool)=>()=>{tools.open=name;};
const commands=computed<Command[]>(()=>[
 {id:'play',label:player.isPlaying?'Пауза':'Воспроизвести',group:'Плеер',icon:player.isPlaying?'pause':'play',keywords:'play pause стоп',action:()=>player.toggle()},
 {id:'lyrics',label:'Текст песни',group:'Плеер',icon:'lyrics',action:()=>{player.showLyrics=!player.showLyrics;}},
 {id:'audio',label:'Темп, тональность и микрофон',group:'Звук',icon:'sliders',keywords:'звук выход устройство запись',action:tool('audio')},
 {id:'local',label:'Локальная библиотека',group:'Музыка',icon:'library',keywords:'дубли теги умные плейлисты bpm энергия файлы',action:tool('library')},
 {id:'ocr',label:'Поиск по скриншоту',group:'Поиск',icon:'search',keywords:'изображение текст распознать',action:tool('ocr')},
 {id:'home',label:'Главное',group:'Разделы',icon:'home',action:route('/')},
 {id:'liked',label:'Мне нравится',group:'Разделы',icon:'heart',action:route('/liked')},
 {id:'stats',label:'Статистика',group:'Разделы',icon:'stats',action:route('/stats')},
 {id:'sleep30',label:'Таймер сна на 30 минут',group:'Плеер',icon:'time',action:()=>sleep.start(30)},
 ...(sleep.active?[{id:'sleepCancel',label:'Выключить таймер сна',group:'Плеер',icon:'time',action:()=>sleep.cancel()}]:[]),
 {id:'eq',label:'Эквалайзер',group:'Настройки',icon:'sliders',action:route('/settings','equalizer')},
 {id:'background',label:'Фон и тема',group:'Настройки',icon:'display',action:route('/settings','backgrounds')},
 {id:'mini',label:'Вид мини-плеера',group:'Настройки',icon:'mini',keywords:'кассета скин',action:route('/settings','mini')},
 {id:'listenbrainz',label:'ListenBrainz',group:'Настройки',icon:'stats',keywords:'история синхронизация',action:route('/settings','listenbrainz')},
 ...library.playlists.map(p=>({id:`playlist:${p.kind}`,label:p.title,group:'Плейлист',icon:'queue',action:route(`/playlists/${p.kind}`)})),
 ...[...new Map(player.queue.map((t:Track)=>[t.id,t])).values()].map(t=>({id:`track:${t.id}`,label:t.title,group:t.artists.map(a=>a.name).join(', '),icon:'note',action:()=>{const index=player.queue.findIndex(x=>x.id===t.id);if(index>=0)void player.playQueue(player.queue,index);}})),
]);
const results=computed(()=>{const out=commands.value.map(c=>({c,score:commandScore(`${c.label} ${c.keywords??''} ${c.group}`,query.value)})).filter(x=>x.score).sort((a,b)=>b.score-a.score).map(x=>x.c).slice(0,35);if(query.value.trim().length>=2)out.push({id:'search',label:`Искать музыку: ${query.value.trim()}`,icon:'search',group:'Поиск',action:()=>{void router.push({path:'/search',query:{q:query.value.trim()}});}});return out;});
function move(delta:number){if(results.value.length)selected.value=(selected.value+delta+results.value.length)%results.value.length;void nextTick(()=>document.querySelector('.command-results [aria-selected=true]')?.scrollIntoView({block:'nearest'}));}
function run(index:number){const item=results.value[index];if(!item)return;emit('update:modelValue',false);void nextTick(item.action);}
watch(query,()=>selected.value=0);watch(()=>props.modelValue,async open=>{if(open){query.value='';selected.value=0;await nextTick();input.value?.focus();}});
</script>
<style scoped>.command-palette{margin-top:min(14vh,100px);width:640px;max-width:calc(100vw - 32px);background:var(--surface);color:var(--fg);border:1px solid var(--line);border-radius:13px;box-shadow:0 20px 90px #0006}.command-search{display:flex;gap:14px;align-items:center;padding:18px;border-bottom:1px solid var(--line)}.command-search input{min-width:0;flex:1;background:none;border:0;color:var(--fg);outline:0;font:inherit}.command-search kbd{font-size:11px;color:var(--fg-dim)}.command-results{max-height:min(54vh,440px);overflow:auto;padding:7px}.command-results button{width:100%;display:flex;align-items:center;gap:12px;padding:12px;border:0;border-radius:7px;background:transparent;color:var(--fg);text-align:left;cursor:pointer;font:inherit;font-size:13px}.command-results button.on{background:var(--hover)}.command-results button>span{flex:1}.command-results small{color:var(--fg-dim);font-size:11px;max-width:30%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.command-results p{padding:18px;color:var(--fg-dim)}footer{display:flex;gap:18px;font-size:11px;color:var(--fg-dim);padding:11px 18px;border-top:1px solid var(--line)}</style>
